"""Dosya sistemi erisim arayuzu.

GUI yalnizca bu arayuzu tanir. Yeni bir dosya sistemi destegi eklendiginde
(ornegin ext4 okuyucu) burada yeni bir sinif tanimlanip `open_filesystem`
icine baglanir; arayuz tarafinda degisiklik gerekmez.
"""
from __future__ import annotations

import contextlib
import datetime
import io
import os
from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple

from .exfat import ExEntry, ExFatError, ExFatFS
from .extread import ExtError, ExtFS
from .extwrite import ExtWriter
from .ntfsread import NtfsEntry, NtfsError, NtfsFS
from .platform import restore_owner
from .ntfswrite import NtfsWriter
from .fat import ATTR_DIRECTORY, DirEntry, FatError, FatFS
from .fsdetect import FSInfo, detect
from .image import BlockDevice
from .hfsplus import HfsEntry, HfsError, HfsPlusFS
from .hfswrite import HfsWriter
from .iso9660 import IsoEntry, IsoError, IsoFS
from .udf import UdfEntry, UdfError, UdfFS
from .xfs import XfsEntry, XfsError, XfsFS
from .btrfs import BtrfsEntry, BtrfsError, BtrfsFS
from .f2fs import F2fsEntry, F2fsError, F2fsFS
from .apfs import ApfsEntry, ApfsError, ApfsFS
from .compress import DecompressError
from .udfwrite import UdfWriter
from ..i18n import tr


@dataclass
class FileNode:
    name: str
    path: str
    is_dir: bool = False
    size: int = 0
    mtime: Optional[datetime.datetime] = None
    attr_text: str = ""
    hidden: bool = False
    readonly: bool = False


PROGRESS_STEP = 1024 * 1024        # dosya ekleme ilerlemesi bildirim araligi


class FileSystemAccess:
    """Bolum icerigine erisim icin ortak arayuz."""

    fs_type: str = ""
    label: str = ""
    writable: bool = False
    readable: bool = False

    @property
    def write_reason(self) -> str:
        """Yazma neden kapali? Yazilabiliyorsa bos dize.

        Iki ayri neden vardir ve kullaniciya ayni gorunmemelidir:
        kaynagin salt okunur acilmasi (cozulebilir) ile surucunun yazma
        destegi olmamasi (cozulemez). Her sinif kendi nedenini soyler.
        """
        return "" if self.writable else tr("Bu bolume yazilamiyor.")

    def write_possible(self) -> Tuple[bool, str]:
        """Kaynak yazma kipine alininca bu bolume yazilabilir mi; (evet, neden).

        `writable` kaynagin **su anki** kipine baglidir. Kaynak artik hep
        salt okunur acildigi icin (ADR 0025) kuyruga yazan bir adim eklemeye
        karar verirken o yetmez: fiziksel diskte etiket degistirme ve bos
        alan silme hic secilemiyordu (gozlemci gezinti testi, 2026-10-14).
        Varsayilan: su anki durum; aygittan bagimsiz karar verebilen
        suruculer bunu ezer.
        """
        return self.writable, ("" if self.writable else self.write_reason)

    def label_possible(self) -> Tuple[bool, str]:
        """Birim etiketi (kuyrukta, Uygula'da) degistirilebilir mi."""
        if type(self).set_label is FileSystemAccess.set_label:
            return False, ""
        return self.write_possible()

    def listdir(self, path: str = "/") -> List[FileNode]:
        raise NotImplementedError

    def read(self, path: str, max_bytes: int = -1) -> bytes:
        raise NotImplementedError

    def extract(self, path: str, dest: str) -> str:
        raise NotImplementedError

    def iter_read(self, path: str):
        """Dosyayi parca parca verir. Alt siniflar akisla saglar (ADR 0081);
        burasi tek parca okuyan yedek yoldur."""
        yield self.read(path)

    def _extract_stream(self, path: str, dest: str) -> str:
        """`iter_read` ile dosyayi diske yazar (bellek dosya boyutundan bagimsiz)."""
        with open(dest, "wb") as fh:
            for piece in self.iter_read(path):
                fh.write(piece)
        restore_owner(dest)     # yetkili kopyada dosya root'a ait kalmasin
        return dest

    def write_file(self, path: str, data: bytes) -> FileNode:
        return self.write_stream(path, io.BytesIO(data), len(data))

    def write_stream(self, path: str, src, size: int) -> FileNode:
        """Kaynaktan `size` bayti dosya olarak yazar; bellek dosya boyutundan
        bagimsizdir (ADR 0081). Yazilabilen her dosya sistemi bunu saglar."""
        raise NotImplementedError

    def import_file(self, local_path: str, dest_dir: str = "/") -> FileNode:
        """Yerel dosyayi parca parca okuyarak kopyalar (tek parca okumaz)."""
        name = os.path.basename(local_path)
        target = (dest_dir.rstrip("/") + "/" + name) if dest_dir != "/" else "/" + name
        with open(local_path, "rb") as fh:
            return self.write_stream(target, fh, os.fstat(fh.fileno()).st_size)

    # Bolumun aygiti (PartitionView); open_filesystem atar. Yazilan bayti
    # saymak icin kullanilir (ilerleme), dosya sistemi kodu buna dokunmaz.
    device: Optional[BlockDevice] = None

    @contextlib.contextmanager
    def _watch_writes(self, on_bytes):
        """Bu blok boyunca aygita yazilan bayt `on_bytes(n)` ile bildirilir."""
        dev = self.device
        if dev is None or on_bytes is None:
            yield
            return
        previous = dev.__dict__.get("write_observer")
        dev.write_observer = on_bytes
        try:
            yield
        finally:
            if previous is None:
                dev.__dict__.pop("write_observer", None)
            else:
                dev.write_observer = previous

    def _import_with_progress(self, source: str, target: str, size: int,
                              done: int, total: int, progress) -> None:
        """Tek dosya; ilerleme dosyanin ICINDE de yurur (yazilan bayta gore).

        Yazilan bayt veri + metaveridir; dosya boyunu asmamasi icin kirpilir.
        """
        name = os.path.basename(source)
        if progress is None:
            self.import_file(source, target)
            return
        written = [0, 0]                 # yazilan, son bildirilen (kirpilmis)

        def on_bytes(n: int) -> None:
            # FAT sektor sektor yazar (40 MB = 80 000 yazim); her birini
            # bildirmek arayuzu sinyale bogar. ~1 MB'ta bir bildirilir.
            # Kirpilmis deger karsilastirilir: kucuk dosyada metaveri (FAT
            # kopyalari) dosyadan cok yazilir, ayni degeri tekrar bildirmek
            # anlamsizdir.
            written[0] += n
            shown = min(written[0], size)
            if shown - written[1] >= PROGRESS_STEP:
                written[1] = shown
                progress(done + shown, total, name)

        progress(done, total, name)
        with self._watch_writes(on_bytes):
            self.import_file(source, target)

    def import_files(self, paths: List[str], dest_dir: str = "/",
                     progress=None) -> tuple:
        """Dosyalari tek tek ekler; (eklenen, sorunlar) dondurur.

        `progress(yapilan_bayt, toplam_bayt, ad)` dosya yazilirken de
        cagrilir: tek buyuk dosyada bile cubuk ilerler ve kalan sure
        hesaplanabilir. Bir dosyanin hatasi digerlerini durdurmaz.
        """
        sizes = []
        for path in paths:
            try:
                sizes.append(os.path.getsize(path))
            except OSError:
                sizes.append(0)
        total = sum(sizes)
        done = copied = 0
        problems: List[str] = []
        for path, size in zip(paths, sizes):
            try:
                self._import_with_progress(path, dest_dir, size, done, total,
                                           progress)
                copied += 1
            except Exception as exc:                     # noqa: BLE001
                problems.append(f"{os.path.basename(path)}: {exc}")
            done += size
        if progress is not None:
            progress(total, total, "")
        return copied, problems

    def import_tree(self, local_dir: str, dest_dir: str = "/", progress=None) -> int:
        """Yerel klasoru birime kopyalar; kopyalanan dosya sayisini dondurur.

        Tek uygulama burada durur; her dosya sistemi kendi `mkdir` ve
        `import_file` islevleriyle kullanilir. Daha once dort ayri kopya vardi
        ve ikisi hedefte **ust klasoru olusturmuyordu** — ayni dugme dosya
        sistemine gore farkli sonuc veriyordu.

        `progress(yapilan_bayt, toplam_bayt, ad)`: verilirse her dosyadan once
        cagrilir. Arayuz ilerleme penceresini bununla besler; buyuk bir kopyanin
        sessizce surmesi kullaniciya donma gibi gorunuyordu.
        """
        files: List[tuple] = []
        total = 0
        base = os.path.basename(os.path.normpath(local_dir))
        root_target = dest_dir.rstrip("/") + "/" + base
        for root, _dirs, names in os.walk(local_dir):
            rel = os.path.relpath(root, local_dir).replace(os.sep, "/")
            target = root_target if rel == "." else f"{root_target}/{rel}"
            for name in sorted(names):
                source = os.path.join(root, name)
                try:
                    size = os.path.getsize(source)
                except OSError:
                    continue
                files.append((source, target, size))
                total += size

        made = {""}
        done = 0
        count = 0
        for source, target, size in files:
            # Hedef klasor zinciri dosyadan once olusturulur; var olani
            # olusturmaya calismak dosya sistemine gore hata firlatir.
            if target not in made:
                self._ensure_dir(target)
                made.add(target)
            self._import_with_progress(source, target, size, done, total,
                                       progress)
            done += size
            count += 1
        if not files:
            self._ensure_dir(root_target)
        if progress is not None:
            progress(done, total, "")
        return count

    def _ensure_dir(self, path: str) -> None:
        """Klasor zincirini olusturur; var olanlari atlar."""
        parts = [p for p in path.replace("\\", "/").split("/") if p]
        current = ""
        for part in parts:
            current += "/" + part
            try:
                self.mkdir(current)
            except Exception:
                pass            # zaten var ya da olusturulamaz; import_file soyler

    def mkdir(self, path: str) -> None:
        raise NotImplementedError

    def remove(self, path: str, recursive: bool = True) -> None:
        raise NotImplementedError

    def rename(self, path: str, new_name: str) -> None:
        raise NotImplementedError

    def set_label(self, label: str) -> None:
        raise NotImplementedError

    def stats(self) -> Dict[str, int]:
        return {}

    def flush(self) -> None:
        pass


class FatAccess(FileSystemAccess):
    """Saf Python FAT surucusu uzerinden tam okuma/yazma erisimi."""

    readable = True

    def __init__(self, view: BlockDevice):
        self.fs = FatFS(view)
        self.fs_type = self.fs.fs_type_name
        self.label = self.fs.label
        # Tutarsiz FAT (fat_problem) okunur ama yazilmaz
        self.writable = not self.fs.readonly and not self.fs.write_block_reason

    @staticmethod
    def _node(entry: DirEntry, parent: str) -> FileNode:
        path = parent.rstrip("/") + "/" + entry.name
        return FileNode(name=entry.name, path=path, is_dir=entry.is_dir,
                        size=entry.size, mtime=entry.mtime,
                        attr_text=entry.attr_text, hidden=entry.is_hidden,
                        readonly=entry.is_readonly)

    def listdir(self, path: str = "/") -> List[FileNode]:
        return [self._node(e, path) for e in self.fs.listdir(path)]

    def read(self, path: str, max_bytes: int = -1) -> bytes:
        return self.fs.read_file(path, max_bytes)

    def iter_read(self, path: str):
        return self.fs.iter_file(path)

    def extract(self, path: str, dest: str) -> str:
        return self.fs.extract(path, dest)

    def write_stream(self, path: str, src, size: int) -> FileNode:
        parent = "/" + "/".join(path.replace("\\", "/").split("/")[:-1]).strip("/")
        return self._node(self.fs.write_stream(path, src, size), parent)

    def mkdir(self, path: str) -> None:
        self.fs.mkdir(path)

    def remove(self, path: str, recursive: bool = True) -> None:
        self.fs.remove(path, recursive=recursive)

    def rename(self, path: str, new_name: str) -> None:
        self.fs.rename(path, new_name)

    def write_possible(self) -> Tuple[bool, str]:
        reason = self.fs.write_block_reason or ""
        return not reason, reason

    def set_label(self, label: str) -> None:
        self.fs.set_label(label)
        self.label = label

    @property
    def write_reason(self) -> str:
        if self.writable:
            return ""
        if self.fs.write_block_reason:
            return self.fs.write_block_reason
        return (tr("Kaynak salt okunur acildi. Goruntuyu/diski yazma modunda "
                "acarsaniz bu bolume yazabilirsiniz."))

    def stats(self) -> Dict[str, int]:
        return self.fs.stats()

    def flush(self) -> None:
        self.fs.flush()


