class FatFS:
    """Bagli bir FAT birimi."""

    def __init__(self, dev: BlockDevice):
        self.dev = dev
        self._fat_cache: Optional[bytearray] = None
        self._fat_dirty = False
        self._free_count: Optional[int] = None
        self._next_free = 2
        self._fat_problem: Optional[str] = None
        self._mount()

    # ---- baglama -----------------------------------------------------------
    def _mount(self) -> None:
        boot = self.dev.read(0, 512)
        if boot[510:512] != b"\x55\xAA":
            raise FatError(tr("FAT onyukleme sektoru imzasi yok"))
        self.bytes_per_sector = struct.unpack_from("<H", boot, 11)[0]
        self.sectors_per_cluster = boot[13]
        self.reserved_sectors = struct.unpack_from("<H", boot, 14)[0]
        self.num_fats = boot[16]
        self.root_entries = struct.unpack_from("<H", boot, 17)[0]
        total16 = struct.unpack_from("<H", boot, 19)[0]
        self.media = boot[21]
        fat16_size = struct.unpack_from("<H", boot, 22)[0]
        total32 = struct.unpack_from("<I", boot, 32)[0]
        if self.bytes_per_sector not in (512, 1024, 2048, 4096):
            raise FatError(tr("Gecersiz sektor boyutu"))
        if self.sectors_per_cluster == 0 or self.num_fats == 0:
            raise FatError(tr("Gecersiz BPB"))
        self.total_sectors = total16 or total32
        self.fat_size = fat16_size or struct.unpack_from("<I", boot, 36)[0]
        self.root_dir_sectors = (self.root_entries * 32 + self.bytes_per_sector - 1) \
            // self.bytes_per_sector
        self.first_data_sector = (self.reserved_sectors
                                  + self.num_fats * self.fat_size
                                  + self.root_dir_sectors)
        data_sectors = self.total_sectors - self.first_data_sector
        if data_sectors <= 0:
            raise FatError(tr("Gecersiz FAT yerlesimi"))
        self.cluster_count = data_sectors // self.sectors_per_cluster
        # Tip BPB yapisindan belirlenir: BPB_FATSz16 == 0 ise FAT32'dir (Linux
        # `fat_length == 0`, Windows fastfat `IsBpbFat32`). Yalnizca kume
        # sayisina bakmak, `mkdosfs -F 32` ile kucuk bolumde uretilmis
        # (65525'ten az kumeli) FAT32'yi FAT16 sanar; o durumda 16 bitlik
        # girdi yazmak tabloyu bozar.
        if fat16_size == 0:
            self.fat_type = 32
        elif self.cluster_count < FAT12_MAX + 1:
            self.fat_type = 12
        else:
            self.fat_type = 16
        self.root_cluster = struct.unpack_from("<I", boot, 44)[0] if self.fat_type == 32 else 0
        self.fsinfo_sector = struct.unpack_from("<H", boot, 48)[0] if self.fat_type == 32 else 0
        # FAT32 BPB_ExtFlags: bit 7 = aynalama kapali, bit 0-3 = etkin FAT.
        # Aynalama kapaliyken surucu yalnizca etkin FAT'i okur/yazar; digerleri
        # bayat olabilir (Microsoft FAT spec, BPB_ExtFlags).
        ext_flags = struct.unpack_from("<H", boot, 40)[0] if self.fat_type == 32 else 0
        self.fat_mirroring = not (ext_flags & 0x80)
        self.active_fat = 0 if self.fat_mirroring else (ext_flags & 0x0F)
        if self.active_fat >= self.num_fats:
            # gecersiz etkin FAT: okuma FAT0'dan, yazma kapali (fat_problem)
            self.active_fat = 0
            self._fat_problem = "ExtFlags etkin FAT %d >= FAT sayisi %d" % (
                ext_flags & 0x0F, self.num_fats)
        # Yedek onyukleme sektoru BPB_BkBootSec'ten okunur (sabit 6 degil)
        self.backup_boot_sector = (struct.unpack_from("<H", boot, 50)[0]
                                   if self.fat_type == 32 else 0)
        sig_off = 0x42 if self.fat_type == 32 else 0x26
        self.has_ext_bpb = boot[sig_off] in (0x28, 0x29)
        label_off = 0x47 if self.fat_type == 32 else 0x2B
        # Etiket ve kimlik yalnizca genisletilmis BPB (imza 0x29) varsa vardir
        bpb_label = ""
        if boot[sig_off] == 0x29:
            bpb_label = boot[label_off:label_off + 11].decode("cp437").strip()
        if bpb_label == "NO NAME":
            bpb_label = ""
        vid_off = 0x43 if self.fat_type == 32 else 0x27
        self.volume_id = struct.unpack_from("<I", boot, vid_off)[0] if self.has_ext_bpb else 0
        # Kok dizindeki etiket girisi once gelir (Windows, blkid, fsck.fat da
        # oyle okur); yoksa BPB'deki etiket.
        root_label = self._root_label_entry()
        self.label = root_label[1] if root_label else bpb_label

    def _root_label_entry(self) -> Optional[Tuple[int, str]]:
        """Kok dizindeki birim etiketi girisi: (dizin verisindeki ofset, ad).

        Kok dizin bastan okunur, ilk etiket ya da dizin sonu bulununca durur;
        cogu birimde ilk kume yeter, FAT tablosu yuklenmez.
        return ""

    @property
    def write_block_reason(self) -> str:
        """Bu birime yazmamak icin neden (bos: yazilabilir)."""
        if self.fat_problem():
            return tr("FAT tablosu tutarsiz; birime yazilamaz. Once fsck.fat "
                      "veya chkdsk ile onarin")
        if self.dirty_state():
            return tr("Birim temiz ayrilmamis (kirli bayragi); FAT ve dizinler "
                      "yarim guncellenmis olabilir. Once Windows'ta chkdsk ya da "
                      "fsck.fat ile denetleyin.")
        return ""

    def _check_writable(self) -> None:
        if self.readonly:
            raise FatError(tr("Birim salt okunur"))
        reason = self.write_block_reason
        if reason:
            raise FatError(reason)

    def fat_offset(self, index: int) -> int:
        """`index`. FAT kopyasinin bayt ofseti."""
        return (self.reserved_sectors + index * self.fat_size) * self.bytes_per_sector

    def _load_fat(self) -> bytearray:
        if self._fat_cache is None:
            self._fat_cache = bytearray(self.dev.read(
                self.fat_offset(self.active_fat),
                self.fat_size * self.bytes_per_sector))
        return self._fat_cache

    def get_fat(self, cluster: int) -> int:
        fat = self._load_fat()
        if self.fat_type == 32:
            return struct.unpack_from("<I", fat, cluster * 4)[0] & 0x0FFFFFFF
        if self.fat_type == 16:
            return struct.unpack_from("<H", fat, cluster * 2)[0]
        off = cluster + (cluster // 2)
        val = struct.unpack_from("<H", fat, off)[0]
        return (val >> 4) if (cluster & 1) else (val & 0x0FFF)

    def set_fat(self, cluster: int, value: int) -> None:
        fat = self._load_fat()
        if self.fat_type == 32:
            old = struct.unpack_from("<I", fat, cluster * 4)[0]
            struct.pack_into("<I", fat, cluster * 4,
                             (old & 0xF0000000) | (value & 0x0FFFFFFF))
        elif self.fat_type == 16:
            struct.pack_into("<H", fat, cluster * 2, value & 0xFFFF)
        else:
            off = cluster + (cluster // 2)
            val = struct.unpack_from("<H", fat, off)[0]
            if cluster & 1:
                val = (val & 0x000F) | ((value & 0x0FFF) << 4)
            else:
                val = (val & 0xF000) | (value & 0x0FFF)
            struct.pack_into("<H", fat, off, val)
        self._fat_dirty = True

    def flush(self) -> None:
        """FAT onbellegini kopyalara yazar.

        Aynalama acikken tum kopyalara; kapaliyken (ExtFlags bit 7) yalnizca
        etkin FAT'e — diger kopyalar surucu icin anlamsizdir ve etkin FAT'i
        bayat bir kopyayla ezmek dosya sistemini bozar.
        """
        if self._fat_dirty and self._fat_cache is not None:
            kopyalar = (range(self.num_fats) if self.fat_mirroring
                        else [self.active_fat])
            for i in kopyalar:
                self.dev.write(self.fat_offset(i), bytes(self._fat_cache))
            self._fat_dirty = False
            self._update_fsinfo()
        f = getattr(self.dev, "flush", None)
        if f:
            f()

    def _update_fsinfo(self) -> None:
        if self.fat_type != 32 or not self.fsinfo_sector:
            return
        try:
            free = self.free_clusters()
            off = self.fsinfo_sector * self.bytes_per_sector
            sector = bytearray(self.dev.read(off, self.bytes_per_sector))
            if sector[0:4] == b"RRaA":
                struct.pack_into("<I", sector, 488, free)
                self.dev.write(off, bytes(sector))
        except Exception:
            pass

    def chain(self, start: int) -> List[int]:
        """Kume zincirini dondurur."""
        out: List[int] = []
        cur = start
        guard = self.cluster_count + 8
        while 2 <= cur <= self.max_cluster and len(out) < guard:
            out.append(cur)
            cur = self.get_fat(cur)
            if cur >= self.eoc or cur == 0:
                break
        return out

    def free_clusters(self) -> int:
        """Bos kume sayisi (onbellekli).

        Sayim FAT tablosu uzerinde toplu yapilir; tahsis/serbest birakma
        sirasinda sayac guncellendigi icin yeniden taranmaz.
        """
        if self._free_count is None:
            self._free_count = self._count_free()
        return self._free_count

    def _count_free(self) -> int:
        import array
        import sys as _sys
        fat = self._load_fat()
        last = self.max_cluster
        if self.fat_type == 32:
            arr = array.array("I")
            ham = bytes(fat[8:(last + 1) * 4])
            arr.frombytes(ham[:len(ham) - len(ham) % 4])
            if _sys.byteorder != "little":
                arr.byteswap()
            return sum(1 for v in arr if (v & 0x0FFFFFFF) == 0)
        if self.fat_type == 16:
            arr = array.array("H")
            ham = bytes(fat[4:(last + 1) * 2])
            arr.frombytes(ham[:len(ham) - len(ham) % 2])
            if _sys.byteorder != "little":
                arr.byteswap()
            return arr.count(0)
        return sum(1 for c in range(2, last + 1) if self.get_fat(c) == 0)

    def alloc_cluster(self, prev: Optional[int] = None) -> int:
        """Bos bir kume ayirir.

        `_next_free` ipucundan taranir; liste uretilmez, boylece ardisik
        tahsisler amortize O(1) olur (buyuk dosya yazmanin sicak yolu).
        """
        start = max(2, getattr(self, "_next_free", 2))
        upper = self.max_cluster
        for span in (range(start, upper + 1), range(2, min(start, upper + 1))):
            for c in span:
                if self.get_fat(c) == 0:
                    self.set_fat(c, self.eoc | 0x7)
                    if prev:
                        self.set_fat(prev, c)
                    self._next_free = c + 1
                    if self._free_count is not None:
                        self._free_count -= 1
                    return c
        raise FatError(tr("Birimde bos kume kalmadi"))

    def free_chain(self, start: int) -> None:
        serbest = 0
        for c in self.chain(start):
            self.set_fat(c, 0)
            serbest += 1
            if c < getattr(self, "_next_free", 2):
                self._next_free = c        # bosalan yeri bir sonraki tahsiste kullan
        if self._free_count is not None:
            self._free_count += serbest

    # ---- kume G/C ----------------------------------------------------------
    def cluster_offset(self, cluster: int) -> int:
        return ((self.first_data_sector + (cluster - 2) * self.sectors_per_cluster)
                * self.bytes_per_sector)

    def read_cluster(self, cluster: int) -> bytes:
        return self.dev.read(self.cluster_offset(cluster), self.cluster_bytes)

    def write_cluster(self, cluster: int, data: bytes) -> None:
        if len(data) < self.cluster_bytes:
            data = data + b"\x00" * (self.cluster_bytes - len(data))
        self.dev.write(self.cluster_offset(cluster), data[:self.cluster_bytes])

    # ---- dizin verisi ------------------------------------------------------
    @property
    def root_dir_offset(self) -> int:
        return ((self.reserved_sectors + self.num_fats * self.fat_size)
                * self.bytes_per_sector)

    def _read_dir(self, cluster: Optional[int]) -> Tuple[bytearray, List[int]]:
        if cluster is None:  # FAT12/16 sabit kok dizin
            return bytearray(self.dev.read(self.root_dir_offset,
                                           self.root_dir_sectors * self.bytes_per_sector)), []
        chain = self.chain(cluster)
        if not chain:
            raise FatError(tr("Bozuk dizin kume zinciri"))
        buf = bytearray()
        for c in chain:
            buf += self.read_cluster(c)
        return buf, chain

    def _write_dir(self, cluster: Optional[int], data: bytearray,

@property
def max_cluster(self) -> int:
    return self.cluster_count + 1  # 2 tabanli

@property
def readonly(self) -> bool:
    return getattr(self.dev, "readonly", False)

# ---- FAT tablosu -------------------------------------------------------
# ---- tutarlilik kapisi --------------------------------------------------
def fat_problem(self) -> str:
    """FAT tablosunun yapisal sorunu (bos: tutarli). Sonuc onbellekte.

    fsck.fat'in (dosfstools fat.c read_fat) kurallari: FAT[0]'in ust
    bitleri hep 1 olmali (FAT12 0xFF?, FAT16 0xFFF?, FAT32 0x0FFFFFF?) —
    degilse "FATs appear to be corrupt"; 2..azami kumelerdeki girdi 1 ya da
    azami kume ile kotu kume isareti arasinda olamaz ("out of range").
    FAT32'de kok dizin kumesi aralikta ve ayrilmis olmali. Okuma yine
    serbesttir (zincir gecersiz baglantida durur, cekirdek gibi); yazma,
    boyutlandirma ve yalnizca dolu alan yedegi reddedilir.
    """
    if self._fat_problem is None:
        try:
            self._fat_problem = self._check_fat()
        except Exception as exc:                 # noqa: BLE001
            self._fat_problem = "FAT okunamadi: %s" % exc
    return self._fat_problem

def _check_fat(self) -> str:
    import array
    import sys as _sys
    fat = self._load_fat()
    bits = self.fat_type
    maxc = self.max_cluster
    if len(fat) < ((maxc + 1) * bits + 7) // 8:
def _write_dir(self, cluster: Optional[int], data: bytearray,
               chain: List[int]) -> None:
    if cluster is None:
        cap = self.root_dir_sectors * self.bytes_per_sector
        if len(data) > cap:
            raise FatError(tr("Kok dizin dolu (FAT16 giris siniri)"))
        self.dev.write(self.root_dir_offset, bytes(data).ljust(cap, b"\x00"))
        return
    need = max(1, (len(data) + self.cluster_bytes - 1) // self.cluster_bytes)
    if len(chain) < need:
        # Yeni kumeler once kendi aralarinda zincirlenir, dizine ancak
        # hepsi ayrilinca baglanir: yer biterse dizin yarim buyumez ve
        # ayrilanlar geri birakilir.
        new: List[int] = []
        try:
            while len(chain) + len(new) < need:
                new.append(self.alloc_cluster(new[-1] if new else None))
        except BaseException:
            if new:
                self.free_chain(new[0])
            raise
        self.set_fat(chain[-1], new[0])
        chain.extend(new)
    padded = bytes(data).ljust(need * self.cluster_bytes, b"\x00")
    for i, c in enumerate(chain[:need]):
        self.write_cluster(c, padded[i * self.cluster_bytes:(i + 1) * self.cluster_bytes])

# ---- giris cozumleme ---------------------------------------------------
def _parse_dir(self, data: bytes, base_path: str = "/") -> List[DirEntry]:
    out: List[DirEntry] = []
    lfn_parts: Dict[int, str] = {}
    lfn_checksum = -1
    lfn_start = -1
    for off in range(0, len(data) - 31, 32):
        raw = data[off:off + 32]
        first = raw[0]
        if first == END_OF_DIR:
            break
        if first == FREE_ENTRY:
            lfn_parts.clear()
            lfn_start = -1
            continue
        attr = raw[11]
        if attr == ATTR_LFN:
            seq = first & 0x3F
            if first & 0x40:
                lfn_parts.clear()
                lfn_checksum = raw[13]
                lfn_start = off
            chars = raw[1:11] + raw[14:26] + raw[28:32]
            text = chars.decode("utf-16-le", "ignore")
            cut = text.find("￿")
            if cut >= 0:
                text = text[:cut]
            cut = text.find("\x00")
            if cut >= 0:
                text = text[:cut]
            lfn_parts[seq] = text
            continue

        short11 = raw[0:11]
        short = self._decode_short(short11, raw[12])
        name = short
        slot_off = off
        slots = 1
        if lfn_parts and _lfn_checksum(short11) == lfn_checksum and lfn_start >= 0:
            name = "".join(lfn_parts[k] for k in sorted(lfn_parts))
            slot_off = lfn_start
            slots = (off - lfn_start) // 32 + 1
        lfn_parts = {}
        lfn_start = -1

        cluster = self.entry_cluster(raw)
        size = struct.unpack_from("<I", raw, 28)[0]
        mtime = struct.unpack_from("<H", raw, 22)[0]
        mdate = struct.unpack_from("<H", raw, 24)[0]
        cdate = struct.unpack_from("<H", raw, 16)[0]
        ctime = struct.unpack_from("<H", raw, 14)[0]
        entry = DirEntry(
            name=name, short_name=short, attr=attr, cluster=cluster,
            size=size, mtime=_from_fat_datetime(mdate, mtime),
            ctime=_from_fat_datetime(cdate, ctime),
            slot_offset=slot_off, slot_count=slots,
            path=(base_path.rstrip("/") + "/" + name) if name not in (".", "..") else base_path)
        out.append(entry)
    return out

def entry_cluster(self, raw: bytes) -> int:
    """Dizin girisinin ilk kumesi.

    Ust sozcuk (ofset 0x14) yalnizca FAT32'de kume numarasinin parcasidir;
    FAT12/16'da OS/2 orada genisletilmis oznitelik tutamacini saklar
    (cekirdekte fat_get_start da yalnizca FAT32'de okur).
    """
    lo = struct.unpack_from("<H", raw, 26)[0]
    if self.fat_type != 32:
        return lo
    return (struct.unpack_from("<H", raw, 20)[0] << 16) | lo

@staticmethod
def _decode_short(short11: bytes, nt_flags: int = 0) -> str:
    # Kisa adlar OEM kod sayfasindadir (CP437: Linux/mkfs.fat varsayilani);
    # ilk bayt 0x05, silinmis isaretiyle karismasin diye 0xE5'in yerine
    # yazilir.
    short11 = bytes(short11)
    if short11[:1] == b"\x05":
        short11 = b"\xE5" + short11[1:]
    base = short11[:8].decode("cp437").rstrip()
    ext = short11[8:].decode("cp437").rstrip()
    if nt_flags & 0x08:
        base = base.lower()
    if nt_flags & 0x10:
        ext = ext.lower()
    return f"{base}.{ext}" if ext else base

# ---- gezinme -----------------------------------------------------------
def _dir_cluster(self, path: str) -> Optional[int]:
    """Yol icin dizin kume numarasi (kok icin FAT32'de root_cluster,
    FAT12/16'da None)."""
    parts = _norm(path)
    cluster: Optional[int] = self.root_cluster if self.fat_type == 32 else None
    cur = "/"
    for part in parts:
        entries = self._list_raw(cluster, cur)
        match = None
        for e in entries:
            if e.name.lower() == part.lower() or e.short_name.lower() == part.lower():
                match = e
                break
        if match is None:
            raise FatError(tr("Yol bulunamadi: {}", path))
        if not match.is_dir:
            raise FatError(tr("Dizin degil: {}", path))
        cluster = match.cluster if match.cluster else (
            self.root_cluster if self.fat_type == 32 else None)
        cur = cur.rstrip("/") + "/" + part
    return cluster

def _list_raw(self, cluster: Optional[int], base_path: str) -> List[DirEntry]:
    data, _chain = self._read_dir(cluster)
    return self._parse_dir(data, base_path)

def listdir(self, path: str = "/", include_hidden: bool = True,
            include_system: bool = False) -> List[DirEntry]:
    """Dizin icerigini dondurur ('.', '..' ve birim etiketi haric)."""
    cluster = self._dir_cluster(path)
    entries = self._list_raw(cluster, path if path.startswith("/") else "/" + path)
    out = []
    for e in entries:
        if e.name in (".", "..") or e.is_volume:
            continue
        if not include_hidden and e.is_hidden:
            continue
        if not include_system and (e.attr & ATTR_SYSTEM) and not include_hidden:
            continue
        out.append(e)
    out.sort(key=lambda e: (not e.is_dir, e.name.lower()))
    return out

def find(self, path: str) -> DirEntry:
    parts = _norm(path)
    if not parts:
        return DirEntry(name="/", attr=ATTR_DIRECTORY,
                        cluster=self.root_cluster, path="/")
    parent = "/" + "/".join(parts[:-1])
    cluster = self._dir_cluster(parent)
    for e in self._list_raw(cluster, parent):
        if e.name.lower() == parts[-1].lower() or e.short_name.lower() == parts[-1].lower():
            return e
    raise FatError(tr("Bulunamadi: {}", path))

def exists(self, path: str) -> bool:
    try:
        self.find(path)
        return True
    except FatError:
        return False

# ---- dosya okuma -------------------------------------------------------
def read_file(self, path: str, max_bytes: int = -1) -> bytes:
    entry = self.find(path)
    if entry.is_dir:
        raise FatError(tr("Dizin dosya olarak okunamaz"))
    return self.read_entry(entry, max_bytes)

def iter_file(self, path: str, chunk: int = CHUNK):
    """Dosyayi parca parca verir; bellek dosya boyutundan bagimsiz (ADR 0081)."""
    entry = self.find(path)
    if entry.is_dir:
        raise FatError(tr("Dizin dosya olarak okunamaz"))
    remaining = entry.size
    if not entry.cluster or remaining <= 0:
        return
    cb = self.cluster_bytes
    per = max(1, chunk // cb)
    for start, count in group_runs(self.chain(entry.cluster)):
        for i in range(0, count, per):
            n = min(per, count - i)
            data = self.dev.read(self.cluster_offset(start + i), n * cb)
            data = data[:remaining]
            remaining -= len(data)
            yield data
            if remaining <= 0:
                return

def read_entry(self, entry: DirEntry, max_bytes: int = -1) -> bytes:
    if entry.cluster == 0 or entry.size == 0:
        return b""
    limit = entry.size if max_bytes < 0 else min(entry.size, max_bytes)
    out = bytearray()
    for c in self.chain(entry.cluster):
        out += self.read_cluster(c)
        if len(out) >= limit:
            break
    return bytes(out[:limit])

def extract(self, path: str, dest: str) -> str:
    """Birimdeki dosyayi yerel diske kopyalar."""
    entry = self.find(path)
    if entry.is_dir:
        return self.extract_tree(path, dest)

class ExFatFS:
    """Bagli bir exFAT birimi."""

    def __init__(self, dev: BlockDevice):
        self.dev = dev
        self._bitmap: Optional[bytearray] = None
        self._bitmap_dirty = False
        self._upcase: Optional[Dict[int, int]] = None
        self._mount()

    # ---- baglama ----------------------------------------------------------
    def _mount(self) -> None:
        boot = self.dev.read(0, 512)
        if boot[3:11] != b"EXFAT   ":
            raise ExFatError(tr("exFAT imzasi bulunamadi"))
        self.partition_offset = struct.unpack_from("<Q", boot, 64)[0]
        self.volume_length = struct.unpack_from("<Q", boot, 72)[0]
        self.fat_offset = struct.unpack_from("<I", boot, 80)[0]
        self.fat_length = struct.unpack_from("<I", boot, 84)[0]
        self.cluster_heap_offset = struct.unpack_from("<I", boot, 88)[0]
        self.cluster_count = struct.unpack_from("<I", boot, 92)[0]
        self.root_cluster = struct.unpack_from("<I", boot, 96)[0]
        self.volume_serial = struct.unpack_from("<I", boot, 100)[0]
        self.volume_flags = struct.unpack_from("<H", boot, 106)[0]
        self.bytes_per_sector = 1 << boot[108]
        self.sectors_per_cluster = 1 << boot[109]
        self.num_fats = boot[110]
        self.percent_in_use = boot[112]
        if self.cluster_count == 0 or self.sectors_per_cluster == 0:
            raise ExFatError(tr("Gecersiz exFAT parametreleri"))
        # VolumeFlags bit 0 (ActiveFat): iki FAT'li (TexFAT) birimde etkin FAT
        # ve bitmap. Okuma etkin kopyadan yapilir; yazma yalnizca tek FAT'li
        # birimde serbesttir (bkz. write_block_reason).
        self.active_fat = (self.volume_flags & 0x01) if self.num_fats > 1 else 0
        self.label = ""
        self.bitmap_cluster = 0
        self.bitmap_length = 0
        self.upcase_cluster = 0
        self.upcase_length = 0
        self._read_root_metadata()

    @property
    def write_block_reason(self) -> str:
        """Bu surucunun guvenle yazamadigi birim icin neden (bos: yazilabilir).

        Iki FAT / iki bitmap (TexFAT) tutulan birimde kopyalar islem
        sirasinda bilerek farklidir; tek kopyayi guncellemek digerini
        bayatlatir.
        """
        if self.num_fats != 1 or self.active_fat != 0:
            return tr("Bu exFAT birimi iki FAT kopyasi (TexFAT) kullaniyor; "
                      "yazma ve boyutlandirma desteklenmiyor")
        if self.volume_flags & 0x0006:
            # VolumeDirty (bit1) / MediaFailure (bit2), spec 3.1.13. Windows
            # baglarken koyar, duzgun ayirirken kaldirir (VM'de olculdu: guc
            # kesilince 0x0002 kaldi). Bitmap/FAT yarim guncellenmis olabilir.
            return tr("exFAT birimi temiz ayrilmamis (VolumeDirty) ya da ortam "
                      "hatasi isaretli; bitmap ve FAT yarim guncellenmis olabilir. "
                      "Once Windows'ta chkdsk ya da fsck.exfat ile denetleyin.")
        return ""

    def _check_writable(self) -> None:
        if self.readonly:
            raise ExFatError(tr("Birim salt okunur"))
        reason = self.write_block_reason
        if reason:
            raise ExFatError(reason)

    def _read_root_metadata(self) -> None:
        """Kok dizindeki bitmap, upcase ve etiket girislerini okur.

    def free_cluster_count(self) -> int:
        bm = self._load_bitmap()
        kullanilan = sum(bin(b).count("1") for b in bm)
        return max(0, self.cluster_count - kullanilan)

    def _find_free_run(self, count: int) -> Optional[int]:
        """`count` adet ardisik bos kume arar."""
        seri = 0
        for c in range(2, self.cluster_count + 2):
            if not self.is_used(c):
                seri += 1
                if seri >= count:
                    return c - count + 1
            else:
                seri = 0
        return None

    def alloc_clusters(self, count: int) -> Tuple[int, bool]:
        """Kume ayirir. (ilk_kume, ardisik_mi) dondurur."""
        if count <= 0:
            return 0, True
        bas = self._find_free_run(count)
        if bas is not None:
            for c in range(bas, bas + count):
                self._set_used(c, True)
            return bas, True
        # ardisik yer yok: dagitik ayir ve FAT zinciri kur
        secilen: List[int] = []
        for c in range(2, self.cluster_count + 2):
            if not self.is_used(c):
                secilen.append(c)
                if len(secilen) == count:
                    break
        if len(secilen) < count:
            raise ExFatError(tr("Birimde yeterli bos alan yok"))
        for i, c in enumerate(secilen):
            self._set_used(c, True)
            self.set_fat(c, secilen[i + 1] if i + 1 < len(secilen) else EOC)
        return secilen[0], False

    def free_chain(self, start: int, count: int, contiguous: bool) -> None:
        for c in self.chain(start, count, contiguous):
            self._set_used(c, False)
            if not contiguous:
                self.set_fat(c, 0)

    def flush(self) -> None:
        """Bitmap ve doluluk yuzdesini diske yazar."""
        if self._bitmap_dirty and self._bitmap is not None:
            clusters = self.chain(
                self.bitmap_cluster,
        return -1

    def write_file(self, path: str, data: bytes, overwrite: bool = True) -> ExEntry:
        return self.write_stream(path, io.BytesIO(data), len(data), overwrite)

    def write_stream(self, path: str, src, size: int,
                     overwrite: bool = True) -> ExEntry:
        """Kaynaktan `size` bayti parca parca yazar (ADR 0081).

        Ust dizin, ad ve bos alan **kume ayrilmadan once** denetlenir; sonraki
        her hatada ayrilan kumeler geri birakilir.
        """
        self._check_writable()
        parcalar = _norm(path)
        if not parcalar:
            raise ExFatError(tr("Gecersiz dosya yolu"))
        name, upper = parcalar[-1], "/" + "/".join(parcalar[:-1])
        check_name(name)
        ref = self._resolve_dir(upper)
        cb = self.cluster_bytes
        gereken = (size + cb - 1) // cb
        mevcut = self._match(self._parse_dir(self._read_dir_ref(ref)[0], upper), name)
        serbest = self.free_cluster_count()
        if mevcut is not None:
            if not overwrite:
                raise ExFatError(tr("Dosya zaten var: {}", path))
            if mevcut.cluster:
                serbest += (mevcut.size + cb - 1) // cb
        if gereken > serbest:
            raise ExFatError(tr("Birimde yeterli bos alan yok"))
        if mevcut is not None:
            self.remove(upper.rstrip("/") + "/" + mevcut.name)
            ref = self._resolve_dir(upper)
        first_cluster, ardisik = 0, True
        if size:
            first_cluster, ardisik = self.alloc_clusters(gereken)
        try:
            if size:
                runs = ([(first_cluster, gereken)] if ardisik else
                        group_runs(self.chain(first_cluster, gereken, False)))
                write_runs(src, size, runs, cb,
                           lambda start, off, data: self.dev.write(
                               self.cluster_offset(start) + off, data))
            blob = self._build_entry_set(name, ATTR_ARCHIVE, first_cluster, size, ardisik)
            self._insert_set(ref, blob)
        except BaseException:
            if size:
                self.free_chain(first_cluster, gereken, ardisik)  # kume sizdirmasin
            raise
        self.flush()
        return self.find(path)

    def import_file(self, local_path: str, dest_dir: str = "/",
                    name: Optional[str] = None) -> ExEntry:
        entry_name = name or os.path.basename(local_path)
        with open(local_path, "rb") as fh:
            return self.write_stream(dest_dir.rstrip("/") + "/" + entry_name, fh,
                                     os.fstat(fh.fileno()).st_size)

    def import_tree(self, local_dir: str, dest_dir: str = "/") -> int:
        sayac = 0
        taban = os.path.basename(os.path.normpath(local_dir))
        target = dest_dir.rstrip("/") + "/" + taban
        if not self.exists(target):
            self.mkdir(target)
        for oge in sorted(os.listdir(local_dir)):
            kaynak = os.path.join(local_dir, oge)
            if os.path.isdir(kaynak):
                sayac += self.import_tree(kaynak, target)
            elif os.path.isfile(kaynak):
                self.import_file(kaynak, target)
                sayac += 1
        return sayac

    def mkdir(self, path: str) -> ExEntry:
        self._check_writable()
        parcalar = _norm(path)
        if not parcalar:
            raise ExFatError(tr("Gecersiz klasor yolu"))
        name, upper = parcalar[-1], "/" + "/".join(parcalar[:-1])
        check_name(name)
        ref = self._resolve_dir(upper)
        if self._match(self._parse_dir(self._read_dir_ref(ref)[0], upper), name):
            raise ExFatError(tr("Zaten var: {}", path))
        cluster, _ardisik = self.alloc_clusters(1)
        try:
            self.set_fat(cluster, EOC)
            self.dev.write(self.cluster_offset(cluster), b"\x00" * self.cluster_bytes)
            blob = self._build_entry_set(name, ATTR_DIRECTORY, cluster,
                                         self.cluster_bytes, False)
            self._insert_set(ref, blob)
        except BaseException:
            self.free_chain(cluster, 1, False)
            raise
        self.flush()
        return self.find(path)

    def makedirs(self, path: str) -> None:
        cur = ""
        for chunk in _norm(path):
            cur += "/" + chunk
            if not self.exists(cur):
                self.mkdir(cur)

    def remove(self, path: str, recursive: bool = False) -> None:
        self._check_writable()
        parcalar = _norm(path)
        if not parcalar:
            raise ExFatError(tr("Kok dizin silinemez"))
        upper = "/" + "/".join(parcalar[:-1])
        ref = self._resolve_dir(upper)
        entry = self._match(self._parse_dir(self._read_dir_ref(ref)[0], upper),
                            parcalar[-1])
        if entry is None:
            raise ExFatError(tr("Bulunamadi: {}", path))
        if entry.is_dir:
            sub = self._child_ref(ref, entry)
            cocuklar = self._parse_dir(self._read_dir_ref(sub)[0], entry.path)
            if cocuklar and not recursive:
                raise ExFatError(tr("Klasor bos degil"))
            for cocuk in cocuklar:
                self.remove(upper.rstrip("/") + "/" + entry.name + "/" + cocuk.name,
                            recursive=True)
        veri, clusters = self._read_dir_ref(ref)
        entry = self._match(self._parse_dir(veri, upper), parcalar[-1]) or entry
        for i in range(entry.slot_count):       # InUse bitini temizle
            veri[entry.slot_offset + i * ENTRY_SIZE] &= 0x7F
        self._store_dir(ref, veri, clusters)
        if entry.cluster:
            cluster_count = max(1, (entry.size + self.cluster_bytes - 1) // self.cluster_bytes)
            self.free_chain(entry.cluster, cluster_count, entry.contiguous)
        self.flush()

    def rename(self, path: str, new_name: str) -> ExEntry:
        self._check_writable()
        check_name(new_name)

def _parse_dir(self, veri: bytes, base_path: str) -> List[ExEntry]:
    """Giris kumelerini (0x85 + 0xC0 + 0xC1...) cozumler."""
    out: List[ExEntry] = []
    i = 0
    while i + ENTRY_SIZE <= len(veri):
        kind = veri[i]
        if kind == 0x00:
            break
        if kind != E_FILE:
            i += ENTRY_SIZE
            continue
        ikincil = veri[i + 1]
        total = (ikincil + 1) * ENTRY_SIZE
        if i + total > len(veri):
            break
        cluster_data = veri[i:i + total]
        attr = struct.unpack_from("<H", cluster_data, 4)[0]
        olusturma = _from_exfat_time(struct.unpack_from("<I", cluster_data, 8)[0])
        degistirme = _from_exfat_time(struct.unpack_from("<I", cluster_data, 12)[0])
        stream = cluster_data[ENTRY_SIZE:2 * ENTRY_SIZE]
        if len(stream) < ENTRY_SIZE or stream[0] != E_STREAM:
            i += total
            continue
        bayraklar = stream[1]
        name_length = stream[3]
        valid = struct.unpack_from("<Q", stream, 8)[0]
        first_cluster = struct.unpack_from("<I", stream, 20)[0]
        size = struct.unpack_from("<Q", stream, 24)[0]
        raw_name = bytearray()
        for n in range(2, ikincil + 1):
            entry = cluster_data[n * ENTRY_SIZE:(n + 1) * ENTRY_SIZE]
            if entry[0] != E_NAME:
                continue
            raw_name += entry[2:32]
        name = decode_name(raw_name, name_length)
        out.append(ExEntry(
            name=name, attr=attr, cluster=first_cluster, size=size,
            mtime=degistirme, ctime=olusturma,
            contiguous=bool(bayraklar & 0x02),
            slot_offset=i, slot_count=ikincil + 1,
            path=base_path.rstrip("/") + "/" + name,
            valid_size=valid))
        i += total
    return out

# ---- gezinme ----------------------------------------------------------
def _match(self, entries: List[ExEntry], name: str) -> Optional[ExEntry]:
    """Adi birimin buyuk harf tablosuyla karsilastirir (spec 7.2.5);
    str.lower Turkce I/i gibi harflerde exFAT'in kuralindan sapar."""
    key = self._upcase_name(name)
    for e in entries:
        if self._upcase_name(e.name) == key:
            return e
    return None

def _resolve_dir(self, path: str) -> "_DirRef":
    ref = self._root_ref()
    for chunk in _norm(path):
        veri, _ = self._read_dir_ref(ref)
        eslesen = self._match(self._parse_dir(veri, ref.path), chunk)
        if eslesen is None:
            raise ExFatError(tr("Yol bulunamadi: {}", path))
        if not eslesen.is_dir:
            raise ExFatError(tr("Dizin degil: {}", path))
        ref = self._child_ref(ref, eslesen)
    return ref

def _dir_cluster(self, path: str) -> int:
    return self._resolve_dir(path).cluster

def _read_dir_path(self, path: str) -> bytearray:
    """Yoldaki dizinin ham verisi (NoFatChain dahil; kurtarma kullanir)."""
    return self._read_dir_ref(self._resolve_dir(path))[0]

def listdir(self, path: str = "/") -> List[ExEntry]:
    ref = self._resolve_dir(path)
    girisler = self._parse_dir(self._read_dir_ref(ref)[0],
                               path if path.startswith("/") else "/" + path)
    girisler.sort(key=lambda e: (not e.is_dir, e.name.lower()))
    return girisler

def find(self, path: str) -> ExEntry:
    parcalar = _norm(path)
    if not parcalar:
        return ExEntry(name="/", attr=ATTR_DIRECTORY, cluster=self.root_cluster,
                       path="/")
    upper = "/" + "/".join(parcalar[:-1])
    ref = self._resolve_dir(upper)
    e = self._match(self._parse_dir(self._read_dir_ref(ref)[0], upper), parcalar[-1])
    if e is None:
        raise ExFatError(tr("Bulunamadi: {}", path))
    return e

def exists(self, path: str) -> bool:
    try:
        self.find(path)
        return True
    except ExFatError:
        return False

# ---- okuma ------------------------------------------------------------
def read_file(self, path: str, max_bytes: int = -1) -> bytes:
    entry = self.find(path)
    if entry.is_dir:
        raise ExFatError(tr("Dizin dosya olarak okunamaz"))
    return self.read_entry(entry, max_bytes)

def _file_runs(self, entry: ExEntry) -> List[Tuple[int, int]]:
    cb = self.cluster_bytes
    count = (entry.size + cb - 1) // cb
    if entry.cluster < 2 or count <= 0:
        return []
    if entry.contiguous:
        return [(entry.cluster, count)]
    return group_runs(self.chain(entry.cluster, count, False))

def _iter_entry(self, entry: ExEntry, limit: int = -1, chunk: int = CHUNK):
    """Dosya icerigini parca parca verir.

    ValidDataLength'in otesi diskte ne olursa olsun **sifir** okunur
    (spec 7.6.4; Windows on ayirmada bu bolgeyi yazmaz, eski icerik
    durur).
    """
    total = entry.size if limit < 0 else min(entry.size, limit)
    valid = min(entry.valid_length, total)
    cb = self.cluster_bytes
    per = max(1, chunk // cb)
    pos = 0
    for start, n_total in self._file_runs(entry):
        for i in range(0, n_total, per):
            if pos >= total:
                return
            n = min(per, n_total - i)
            want = min(n * cb, total - pos)
            if pos >= valid:
                data = bytes(want)
            else:
                data = self.dev.read(self.cluster_offset(start + i), n * cb)[:want]
                if pos + len(data) > valid:
                    data = data[:valid - pos] + bytes(pos + len(data) - valid)
            if not data:
                return
            pos += len(data)
            yield data

